  const f=fenceBlocking(e.x,e.z,e.x+mx*(e.rad+0.35),e.z+mz*(e.rad+0.35)); if(f){ onBlocked(f); e.moving=false; return; }
  const sp=e.speed*(e.slowT>0?1-e.slowF:1); e.x+=mx*sp*dt; e.z+=mz*sp*dt; e.moving=true; e.rot=lerpAngle(e.rot,Math.atan2(mx,mz),1-Math.exp(-dt*9));
